def prime_length(string):
    """Return True if the string length is a prime number, False otherwise"""
    def is_prime(n):
        """Check if a number is prime"""
        if n <= 1:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        max_divisor = int(n**0.5) + 1
        for d in range(3, max_divisor, 2):
            if n % d == 0:
                return False
        return True

    return is_prime(len(string))
